#include "gadgets/files/FileSchemas.hpp"
#include <stdexcept>
namespace batbox::gadgets::files {
Json fileGadgetOutputSchema(const std::string& name){
  if(name=="Read")return value::parse(R"BATBOXSCHEMA({"$schema":"https://json-schema.org/draft/2020-12/schema","anyOf":[{"type":"object","properties":{"type":{"type":"string","const":"text"},"file":{"type":"object","properties":{"filePath":{"description":"The path to the file that was read","type":"string"},"content":{"description":"The content of the file","type":"string"},"numLines":{"description":"Number of lines in the returned content","type":"number"},"startLine":{"description":"The starting line number","type":"number"},"totalLines":{"description":"Total number of lines in the file","type":"number"}},"required":["filePath","content","numLines","startLine","totalLines"],"additionalProperties":false}},"required":["type","file"],"additionalProperties":false},{"type":"object","properties":{"type":{"type":"string","const":"image"},"file":{"type":"object","properties":{"base64":{"description":"Base64-encoded image data","type":"string"},"type":{"description":"The MIME type of the image","type":"string","enum":["image/jpeg","image/png","image/gif","image/webp"]},"originalSize":{"description":"Original file size in bytes","type":"number"},"dimensions":{"description":"Image dimension info for coordinate mapping","type":"object","properties":{"originalWidth":{"description":"Original image width in pixels","type":"number"},"originalHeight":{"description":"Original image height in pixels","type":"number"},"displayWidth":{"description":"Displayed image width in pixels (after resizing)","type":"number"},"displayHeight":{"description":"Displayed image height in pixels (after resizing)","type":"number"}},"additionalProperties":false}},"required":["base64","type","originalSize"],"additionalProperties":false}},"required":["type","file"],"additionalProperties":false},{"type":"object","properties":{"type":{"type":"string","const":"notebook"},"file":{"type":"object","properties":{"filePath":{"description":"The path to the notebook file","type":"string"},"cells":{"description":"Array of notebook cells","type":"array","items":{}}},"required":["filePath","cells"],"additionalProperties":false}},"required":["type","file"],"additionalProperties":false},{"type":"object","properties":{"type":{"type":"string","const":"pdf"},"file":{"type":"object","properties":{"filePath":{"description":"The path to the PDF file","type":"string"},"base64":{"description":"Base64-encoded PDF data","type":"string"},"originalSize":{"description":"Original file size in bytes","type":"number"}},"required":["filePath","base64","originalSize"],"additionalProperties":false}},"required":["type","file"],"additionalProperties":false},{"type":"object","properties":{"type":{"type":"string","const":"parts"},"file":{"type":"object","properties":{"filePath":{"description":"The path to the PDF file","type":"string"},"originalSize":{"description":"Original file size in bytes","type":"number"},"count":{"description":"Number of pages extracted","type":"number"},"outputDir":{"description":"Directory containing extracted page images","type":"string"}},"required":["filePath","originalSize","count","outputDir"],"additionalProperties":false}},"required":["type","file"],"additionalProperties":false},{"type":"object","properties":{"type":{"type":"string","const":"file_unchanged"},"file":{"type":"object","properties":{"filePath":{"description":"The path to the file","type":"string"}},"required":["filePath"],"additionalProperties":false}},"required":["type","file"],"additionalProperties":false}]})BATBOXSCHEMA");
  if(name=="Write")return value::parse(R"BATBOXSCHEMA({"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"type":{"description":"Whether a new file was created or an existing file was updated","type":"string","enum":["create","update"]},"filePath":{"description":"The path to the file that was written","type":"string"},"content":{"description":"The content that was written to the file","type":"string"},"structuredPatch":{"description":"Diff patch showing the changes","type":"array","items":{"type":"object","properties":{"oldStart":{"type":"number"},"oldLines":{"type":"number"},"newStart":{"type":"number"},"newLines":{"type":"number"},"lines":{"type":"array","items":{"type":"string"}}},"required":["oldStart","oldLines","newStart","newLines","lines"],"additionalProperties":false}},"originalFile":{"description":"The original file content before the write (null for new files)","anyOf":[{"type":"string"},{"type":"null"}]},"gitDiff":{"type":"object","properties":{"filename":{"type":"string"},"status":{"type":"string","enum":["modified","added"]},"additions":{"type":"number"},"deletions":{"type":"number"},"changes":{"type":"number"},"patch":{"type":"string"},"repository":{"description":"GitHub owner/repo when available","anyOf":[{"type":"string"},{"type":"null"}]}},"required":["filename","status","additions","deletions","changes","patch"],"additionalProperties":false}},"required":["type","filePath","content","structuredPatch","originalFile"],"additionalProperties":false})BATBOXSCHEMA");
  if(name=="Edit")return value::parse(R"BATBOXSCHEMA({"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"filePath":{"description":"The file path that was edited","type":"string"},"oldString":{"description":"The original string that was replaced","type":"string"},"newString":{"description":"The new string that replaced it","type":"string"},"originalFile":{"description":"The original file contents before editing","type":"string"},"structuredPatch":{"description":"Diff patch showing the changes","type":"array","items":{"type":"object","properties":{"oldStart":{"type":"number"},"oldLines":{"type":"number"},"newStart":{"type":"number"},"newLines":{"type":"number"},"lines":{"type":"array","items":{"type":"string"}}},"required":["oldStart","oldLines","newStart","newLines","lines"],"additionalProperties":false}},"userModified":{"description":"Whether the user modified the proposed changes","type":"boolean"},"replaceAll":{"description":"Whether all occurrences were replaced","type":"boolean"},"gitDiff":{"type":"object","properties":{"filename":{"type":"string"},"status":{"type":"string","enum":["modified","added"]},"additions":{"type":"number"},"deletions":{"type":"number"},"changes":{"type":"number"},"patch":{"type":"string"},"repository":{"description":"GitHub owner/repo when available","anyOf":[{"type":"string"},{"type":"null"}]}},"required":["filename","status","additions","deletions","changes","patch"],"additionalProperties":false}},"required":["filePath","oldString","newString","originalFile","structuredPatch","userModified","replaceAll"],"additionalProperties":false})BATBOXSCHEMA");
  if(name=="Glob")return value::parse(R"BATBOXSCHEMA({"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"durationMs":{"description":"Time taken to execute the search in milliseconds","type":"number"},"numFiles":{"description":"Total number of files found","type":"number"},"filenames":{"description":"Array of file paths that match the pattern","type":"array","items":{"type":"string"}},"truncated":{"description":"Whether results were truncated (limited to 100 files)","type":"boolean"}},"required":["durationMs","numFiles","filenames","truncated"],"additionalProperties":false})BATBOXSCHEMA");
  if(name=="Grep")return value::parse(R"BATBOXSCHEMA({"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"mode":{"type":"string","enum":["content","files_with_matches","count"]},"numFiles":{"type":"number"},"filenames":{"type":"array","items":{"type":"string"}},"content":{"type":"string"},"numLines":{"type":"number"},"numMatches":{"type":"number"},"appliedLimit":{"type":"number"},"appliedOffset":{"type":"number"}},"required":["numFiles","filenames"],"additionalProperties":false})BATBOXSCHEMA");
  throw std::invalid_argument("Unknown file tool schema: "+name);
}
} // namespace batbox::gadgets::files
